    fn grid_and_surviving_entries_own_their_batch_after_other_references_drop() {
        let mut batch = LineRef::batch(vec![
            Line::new(1, 0.0, 0.0, 14.0, 0.0, 0, 0),
            Line::new(2, 0.0, 2.0, 14.0, 2.0, 0, 0),
